// Transpose the matrix a.
void mat_xpose6(double a[6][6])
{
  assert(a != 0);
  double res[6][6];
  // Row 0
  res[0][0] = a[0][0];
  res[0][1] = a[1][0];
  res[0][2] = a[2][0];
  res[0][3] = a[3][0];
  res[0][4] = a[4][0];
  res[0][5] = a[5][0];
  // Row 1
  res[1][0] = a[0][1];
  res[1][1] = a[1][1];
  res[1][2] = a[2][1];
  res[1][3] = a[3][1];
  res[1][4] = a[4][1];
  res[1][5] = a[5][1];
  // Row 2
  res[2][0] = a[0][2];
  res[2][1] = a[1][2];
  res[2][2] = a[2][2];
  res[2][3] = a[3][2];
  res[2][4] = a[4][2];
  res[2][5] = a[5][2];
  // Row 3
  res[3][0] = a[0][3];
  res[3][1] = a[1][3];
  res[3][2] = a[2][3];
  res[3][3] = a[3][3];
  res[3][4] = a[4][3];
  res[3][5] = a[5][3];
  // Row 4
  res[4][0] = a[0][4];
  res[4][1] = a[1][4];
  res[4][2] = a[2][4];
  res[4][3] = a[3][4];
  res[4][4] = a[4][4];
  res[4][5] = a[5][4];
  // Row 5
  res[5][0] = a[0][5];
  res[5][1] = a[1][5];
  res[5][2] = a[2][5];
  res[5][3] = a[3][5];
  res[5][4] = a[4][5];
  res[5][5] = a[5][5];
  memcpy(a, res, 6 * 6 * sizeof(double));
}

static void mat_ref6(double m[6][6], double ref[6][6])
{
  assert(m != 0);
  assert(ref != 0);
  double m2[6][6], iinv[6][6], f;
  mat_cpy6(m, m2);
  mat_unity6(iinv);
  // Empty the lower half of the matrix
  // Row 1
  f = m2[1][0] / m2[0][0];
  m2[1][0] -= f * m2[0][0];
  m2[1][1] -= f * m2[0][1];
  m2[1][2] -= f * m2[0][2];
  m2[1][3] -= f * m2[0][3];
  m2[1][4] -= f * m2[0][4];
  m2[1][5] -= f * m2[0][5];
  f = m2[2][0] / m2[0][0];
  m2[2][0] -= f * m2[0][0];
  m2[2][1] -= f * m2[0][1];
  m2[2][2] -= f * m2[0][2];
  m2[2][3] -= f * m2[0][3];
  m2[2][4] -= f * m2[0][4];
  m2[2][5] -= f * m2[0][5];
  f = m2[3][0] / m2[0][0];
  m2[3][0] -= f * m2[0][0];
  m2[3][1] -= f * m2[0][1];
  m2[3][2] -= f * m2[0][2];
  m2[3][3] -= f * m2[0][3];
  m2[3][4] -= f * m2[0][4];
  m2[3][5] -= f * m2[0][5];
  f = m2[4][0] / m2[0][0];
  m2[4][0] -= f * m2[0][0];
  m2[4][1] -= f * m2[0][1];
  m2[4][2] -= f * m2[0][2];
  m2[4][3] -= f * m2[0][3];
  m2[4][4] -= f * m2[0][4];
  m2[4][5] -= f * m2[0][5];
  f = m2[5][0] / m2[0][0];
  m2[5][0] -= f * m2[0][0];
  m2[5][1] -= f * m2[0][1];
  m2[5][2] -= f * m2[0][2];
  m2[5][3] -= f * m2[0][3];
  m2[5][4] -= f * m2[0][4];
  m2[5][5] -= f * m2[0][5];   // Row 2
  f = m2[2][1] / m2[1][1];
  m2[2][0] -= f * m2[1][0];
  m2[2][1] -= f * m2[1][1];
  m2[2][2] -= f * m2[1][2];
  m2[2][3] -= f * m2[1][3];
  m2[2][4] -= f * m2[1][4];
  m2[2][5] -= f * m2[1][5];
  f = m2[3][1] / m2[1][1];
  m2[3][0] -= f * m2[1][0];
  m2[3][1] -= f * m2[1][1];
  m2[3][2] -= f * m2[1][2];
  m2[3][3] -= f * m2[1][3];
  m2[3][4] -= f * m2[1][4];
  m2[3][5] -= f * m2[1][5];
  f = m2[4][1] / m2[1][1];
  m2[4][0] -= f * m2[1][0];
  m2[4][1] -= f * m2[1][1];
  m2[4][2] -= f * m2[1][2];
  m2[4][3] -= f * m2[1][3];
  m2[4][4] -= f * m2[1][4];
  m2[4][5] -= f * m2[1][5];
  f = m2[5][1] / m2[1][1];
  m2[5][0] -= f * m2[1][0];
  m2[5][1] -= f * m2[1][1];
  m2[5][2] -= f * m2[1][2];
  m2[5][3] -= f * m2[1][3];
  m2[5][4] -= f * m2[1][4];
  m2[5][5] -= f * m2[1][5];   // Row 3
  f = m2[3][2] / m2[2][2];
  m2[3][0] -= f * m2[2][0];
  m2[3][1] -= f * m2[2][1];
  m2[3][2] -= f * m2[2][2];
  m2[3][3] -= f * m2[2][3];
  m2[3][4] -= f * m2[2][4];
  m2[3][5] -= f * m2[2][5];
  f = m2[4][2] / m2[2][2];
  m2[4][0] -= f * m2[2][0];
  m2[4][1] -= f * m2[2][1];
  m2[4][2] -= f * m2[2][2];
  m2[4][3] -= f * m2[2][3];
  m2[4][4] -= f * m2[2][4];
  m2[4][5] -= f * m2[2][5];
  f = m2[5][2] / m2[2][2];
  m2[5][0] -= f * m2[2][0];
  m2[5][1] -= f * m2[2][1];
  m2[5][2] -= f * m2[2][2];
  m2[5][3] -= f * m2[2][3];
  m2[5][4] -= f * m2[2][4];
  m2[5][5] -= f * m2[2][5];   // Row 4
  f = m2[4][3] / m2[3][3];
  m2[4][0] -= f * m2[3][0];
  m2[4][1] -= f * m2[3][1];
  m2[4][2] -= f * m2[3][2];
  m2[4][3] -= f * m2[3][3];
  m2[4][4] -= f * m2[3][4];
  m2[4][5] -= f * m2[3][5];
  f = m2[5][3] / m2[3][3];
  m2[5][0] -= f * m2[3][0];
  m2[5][1] -= f * m2[3][1];
  m2[5][2] -= f * m2[3][2];
  m2[5][3] -= f * m2[3][3];
  m2[5][4] -= f * m2[3][4];
  m2[5][5] -= f * m2[3][5];   // Row 5
  f = m2[5][4] / m2[4][4];
  m2[5][0] -= f * m2[4][0];
  m2[5][1] -= f * m2[4][1];
  m2[5][2] -= f * m2[4][2];
  m2[5][3] -= f * m2[4][3];
  m2[5][4] -= f * m2[4][4];
  m2[5][5] -= f * m2[4][5];
  mat_cpy6(m2, ref);
}


// Calculate the determinant of the matrix.
// Uses mat_ref internally.
double mat_det6(double m[6][6])
{
  double ref[6][6], diag = 1.0;
  mat_ref6(m, ref);
  diag *= ref[0][0];
  diag *= ref[1][1];
  diag *= ref[2][2];
  diag *= ref[3][3];
  diag *= ref[4][4];
  diag *= ref[5][5];
  return diag;
}

// Remove row r and column k from the matrix
void mat_delete(double a[6][6], double b[5][5], int r, int k)
{
  for (int R = 0; R < r; R++) {
    for (int K = 0; K < k; K++) {
      b[R][K] = a[R][K];
    }
    for (int K = k + 1; K < 6; K++) {
      b[R][K - 1] = a[R][K];
    }
  }
  for (int R = r + 1; R < 6; R++) {
    for (int K = 0; K < k; K++) {
      b[R - 1][K] = a[R][K];
    }
    for (int K = k + 1; K < 6; K++) {
      b[R - 1][K - 1] = a[R][K];
    }
  }
}

